<script setup>
import {computed,reactive,ref} from 'vue'
import {useRouter} from 'vue-router'
import {useIrrigation} from '../../data/runtime.js'
import {useListState} from '../../composables/useListState.js'
import StatusBadge from '../../components/StatusBadge.vue'
import Pagination from '../../components/Pagination.vue'
import ResourceForm from './ResourceForm.vue'
import {stageNames,clone} from './resourceUi.js'
const r=useIrrigation(),router=useRouter(),ui=useListState('fields',{filters:{name:'',status:''}}),search=reactive({...ui.filters}),seasonField=ref(null),seasonDraft=ref(null)
const fields=computed(()=>r.state.entities.Field??[]),seasons=computed(()=>r.state.entities.CropSeason??[])
const filtered=computed(()=>fields.value.filter(f=>f.name.includes(ui.filters.name.trim())&&(!ui.filters.status||f.status===ui.filters.status)))
const rows=computed(()=>filtered.value.slice((ui.page-1)*15,ui.page*15)),area=computed(()=>filtered.value.reduce((s,f)=>s+f.areaMu,0).toFixed(1)),activeCount=computed(()=>seasons.value.filter(s=>s.status==='ENABLED'&&filtered.value.some(f=>f.fieldId===s.fieldId)).length)
const active=f=>seasons.value.find(s=>s.fieldId===f.fieldId&&s.status==='ENABLED')
const manager=f=>(r.state.entities.User??[]).find(u=>u.userId===f.managerId)?.name??'—'
function query(){ui.filters={...search};ui.page=1}
function openSeason(f){seasonField.value=clone(f);seasonDraft.value=clone(active(f)??{fieldId:f.fieldId,crop:'',variety:'',plantingDate:'',harvestDate:null,stage:'',status:'ENABLED'})}
const seasonFields=computed(()=>[{key:'fieldId',label:'田块编号',readonly:true},{key:'crop',label:'作物',required:true},{key:'variety',label:'品种',required:true},{key:'plantingDate',label:'播种日期',type:'date',required:true},{key:'stage',label:'当前生育期',options:Object.entries(stageNames).map(([value,label])=>({value,label})),required:true},{key:'harvestDate',label:'收获日期（归档现季后可新建下一季）',type:'date'}])
function view(f){ui.selectedId=f.fieldId;router.push('/fields/'+f.fieldId)}
</script>
<template><div class="page-stack fields-screen"><form class="field-toolbar" @submit.prevent="query"><label>田块名称<input v-model="search.name" placeholder="请输入田块名称"/></label><label>状态<select v-model="search.status"><option value="">全部状态</option><option value="ENABLED">启用</option><option value="DISABLED">停用</option></select></label><button class="btn btn-primary">查询</button><button type="button" class="btn btn-primary create-field" :disabled="!r.can('FIELD_CREATE')" @click="router.push('/fields/new')">新增田块</button></form><div class="field-summary"><span class="field-symbol">▥</span><span><strong>{{filtered.length}}</strong> 个田块　·　<strong>{{area}}</strong> 亩　·　<strong>{{activeCount}}</strong> 个活动种植季</span></div><div class="field-cards"><article v-for="f in rows" :key="f.fieldId" class="panel field-card"><header><h3>{{f.name}}</h3><StatusBadge :status="f.status"/></header><dl><dt>面积</dt><dd>{{f.areaMu.toFixed(1)}} 亩</dd><dt>编号</dt><dd>{{f.code}}</dd><dt>土壤</dt><dd>{{f.soilType}}</dd><dt>负责人</dt><dd>{{manager(f)}}</dd></dl><div class="field-card-bottom"><span><i>作物阶段</i> {{active(f)?.crop??'未建种植季'}} · {{stageNames[active(f)?.stage]??'—'}}</span><button class="btn btn-sm" @click="view(f)">查看</button><button class="btn btn-sm btn-primary" :disabled="!r.can('SEASON_CREATE',f)" @click="openSeason(f)">种植季</button></div></article></div><div v-if="!filtered.length" class="empty-state">暂无符合条件的田块</div><Pagination v-model="ui.page" :total="filtered.length" compact/><ResourceForm v-if="seasonDraft" :key="seasonField.fieldId" title="种植季信息" :action="seasonDraft.seasonId?'SEASON_UPDATE':'SEASON_CREATE'" :record="seasonDraft" :expected-versions="{[seasonField.fieldId]:seasonField.version}" :fields="seasonFields" @close="seasonDraft=null"/></div></template>
<style scoped>.fields-screen{gap:14px}.field-toolbar{display:flex;align-items:center;gap:22px;min-height:47px}.field-toolbar label{display:flex;align-items:center;gap:16px;white-space:nowrap;color:#4a646a}.field-toolbar input{width:377px}.field-toolbar select{width:240px}.create-field{margin-left:auto}.field-summary{height:62px;border:1px solid #d7eadd;border-radius:8px;background:#ecf6ef;display:flex;align-items:center;gap:22px;padding:0 24px;color:#173d32}.field-summary strong{font-size:28px;color:#087f4c}.field-symbol{font-size:37px;color:#13915c}.field-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:11px}.field-card{height:140px;padding:10px 17px}.field-card header{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}.field-card h3{margin:0;font-size:18px}.field-card dl{display:grid;grid-template-columns:55px 1fr 45px 1.2fr;gap:5px 10px;margin:0;font-size:13px}.field-card dt,.field-card i{color:#758d91;font-style:normal}.field-card dd{margin:0;white-space:nowrap}.field-card-bottom{display:flex;gap:7px;align-items:center;margin-top:6px;font-size:13px}.field-card-bottom span{margin-right:auto;white-space:nowrap}.field-card .btn-sm{padding:3px 15px}.fields-screen :deep(.pagination){margin-top:0}.field-card-bottom i{margin-right:8px}@media(max-width:1250px){.field-cards{grid-template-columns:repeat(2,minmax(0,1fr))}.field-toolbar input{width:220px}.field-toolbar select{width:160px}}@media(max-width:750px){.field-cards{grid-template-columns:1fr}.field-toolbar{flex-wrap:wrap}}
</style>
